ALL = {**OV, **POW, **CARDS}
for fn in glob.glob(f"{ENG}/*.json"):
    base=os.path.basename(fn); e=load(fn); sp=os.path.join(ESP,base)
    out=load(sp) if os.path.exists(sp) else dict(e)
    table = KW_KEYWORDS if base=="card_keywords.json" else (KW_TIPS if base=="static_hover_tips.json" else ALL)
    for k,v in e.items():
        if not isinstance(v,str): out[k]=v; continue
        if k in table: out[k]=table[k]
        elif v in RULES: out[k]=RULES[v]
    json.dump(out,open(sp,"w",encoding="utf-8"),ensure_ascii=False,indent=2)
print("MeiLin traducido")
